import { useEffect, useState } from "react";
import { InitializePaymentErrorCode, UpdatePaymentErrorCode } from "@parksandresorts/webapiproxy-types";
import {
  useAddGiftCardToCart,
  useAddVoucherToCart,
  useCart,
  useCreatePayment,
  usePayment,
  usePaymentStyles,
  useRemoveGiftCardFromCart,
  useRemoveVoucherFromCart,
} from "@/core/hooks";
import { KlarnaCheckout } from "@/core/components/modules/klarna-checkout/klarna-checkout";
import { LanguageHelper, extract, parseServerError, paymentErrorResponseFromServer } from "@/core/helpers";
import { cartToBeginCheckoutGTMEvent, trackEcommerceEvent } from "@/core/helpers/gtm-helper";
import { GiftCardList } from "@/core/components/primitives/gift-card-list/gift-card-list";
import { Modal } from "@/core/components/primitives/modal/modal";
import { MODAL_PORTAL_ID } from "@/core/components/primitives/modal-portal/modal-portal";
import styles from "./shop-service-payment.module.less";
import Banner, { BannerProps } from "@/core/components/primitives/banner/banner";
import { Translation } from "@/core/labels/i18n";
import { useTranslation } from "react-i18next";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { ZeroCostCheckout } from "@/core/components/modules/zero-cost-checkout/zero-cost-checkout";
import AuthAware from "../../hocs/auth-aware/auth-aware";
import { useProducts } from "@/core/hooks/product-hooks";
import { NetsCheckout } from "@/core/components/modules/nets-checkout/nets-checkout";
import { useStaticConfigContext } from "@/core/contexts";
import { CheckoutError, CheckoutLoading } from "@/core/components/primitives/shop-service-status/shop-service-status";
import { GiftCardAndVoucherForm } from "@/core/components/primitives/gift-card-and-voucher-form/gift-card-and-voucher-form";
import { ShopUrlSlugOverrides } from "@/core/types/shop-service-types";

const toGiftCardError = (t: Translation, error: unknown): null | Pick<BannerProps, "heading" | "paragraph"> => {
  if (!error) return null;
  const parsedError = parseServerError(error, paymentErrorResponseFromServer);
  if (!parsedError) {
    return {
      heading: t("somethingWentWrong"),
      // for unknown errors, use `lodash.extract` to attempt to get _some_ information
      paragraph: extract(error, "error.message", undefined),
    };
  }

  switch (parsedError.error.error) {
    case UpdatePaymentErrorCode.GIFT_CARD_IS_NOT_VALID:
    case InitializePaymentErrorCode.GIFT_CARD_IS_NOT_VALID:
      return {
        heading: t("giftCardError.invalidHeading"),
        paragraph: t("giftCardError.invalidParagraph"),
      };
    case UpdatePaymentErrorCode.GIFT_CARD_INVALID_PASS_CODE:
    case InitializePaymentErrorCode.GIFT_CARD_INVALID_PASS_CODE:
      return {
        heading: t("giftCardError.invalidPassCodeHeading"),
        paragraph: t("giftCardError.invalidPassCodeParagraph"),
      };
    case UpdatePaymentErrorCode.GIFT_CARD_HAS_EXPIRED:
    case InitializePaymentErrorCode.GIFT_CARD_HAS_EXPIRED:
      return {
        heading: t("giftCardError.expiredHeading"),
        paragraph: t("giftCardError.expiredParagraph"),
      };
    case UpdatePaymentErrorCode.GIFT_CARD_HAS_NO_BALANCE:
    case InitializePaymentErrorCode.GIFT_CARD_HAS_NO_BALANCE:
      return {
        heading: t("giftCardError.noBalanceHeading"),
        paragraph: t("giftCardError.noBalanceParagraph"),
      };
    default:
      return {
        heading: t("somethingWentWrong"),
        paragraph: parsedError.error.message ?? undefined,
      };
  }
};

export type ShopServicePaymentProps = {
  cartId: string | undefined;
  enabled: boolean;
  shopUrlSlugOverrides?: ShopUrlSlugOverrides;
};

export const ShopServicePayment = AuthAware<ShopServicePaymentProps>(function InnerShopServicePayment({
  cartId,
  enabled,
  shopUrlSlugOverrides,
}) {
  const { t } = useTranslation();
  const locale = LanguageHelper.currentLocale;

  const [modalState, setModalState] = useState<
    | { state: "hidden" }
    // Storing ref to the button element to focus it when the modal closes
    | { state: "open"; button?: HTMLButtonElement }
  >({ state: "hidden" });

  const {
    eCommerce: { preferredPaymentProvider },
  } = useStaticConfigContext();

  const { data: cart, isLoading: isCartLoading, error: cartError } = useCart(cartId);

  const { component: stylingComponent, paymentStyling } = usePaymentStyles(preferredPaymentProvider);

  const { isLoading: isPaymentLoading, error: paymentError } = useCreatePayment(
    cart?.cartGuid ?? "", // This is fine, since we have `!!cart` in the `shouldLoad` parameter (below)
    locale,
    enabled && !!cart,
    undefined,
    preferredPaymentProvider === "Klarna"
      ? {
          preferredPaymentProvider,
          styling: paymentStyling?.klarna,
          shopUrls: shopUrlSlugOverrides,
        }
      : { preferredPaymentProvider: "Nets" },
  );

  const { data: payment } = usePayment(cartId ?? "");

  const { productList: productsInCart } = useProducts(cart?.cartItems.map((item) => item.productId) ?? []);
  const allowedToUseGiftCard = !productsInCart.some((p) => p?.glkProduct.flags.cannotBePurchasedWithGiftCard === true);

  const {
    mutateAsync: addGiftCardMutation,
    isPending: addGiftCardPending,
    error: addGiftCardError,
    reset,
  } = useAddGiftCardToCart(cart?.cartGuid ?? "");
  const { mutate: removeGiftCard, isPending: removeGiftCardPending } = useRemoveGiftCardFromCart(cart?.cartGuid ?? "");

  const {
    mutate: addVoucherMutation,
    isPending: addVoucherPending,
    error: addVoucherError,
    reset: resetVoucherMutation,
    variables: addVoucherVariables,
  } = useAddVoucherToCart(cart?.cartGuid ?? "");

  const { mutate: removeVoucherMutation, isPending: removeVoucherPending } = useRemoveVoucherFromCart(
    cart?.cartGuid ?? "",
  );

  const isLoading =
    isCartLoading || isPaymentLoading || addGiftCardPending || addVoucherPending || removeGiftCardPending;
  const error = cartError ?? paymentError;

  const gcError = toGiftCardError(t, addGiftCardError);

  const voucherError = addVoucherError
    ? {
        heading: t("somethingWentWrong"),
        paragraph: addVoucherError.type === "description" ? addVoucherError.text : t(addVoucherError.labelKey),
      }
    : undefined;

  // This is a proxy for the cart items and their quantities, which are the only things in the cart that we care about changing
  const hashOfCartItems = cart?.cartItems.map((item) => `${item.cartItemGuid} * ${item.quantity}`).join(",");
  useEffect(() => {
    if (!enabled || !cart || cart.cartItems.length === 0) return;

    trackEcommerceEvent(cartToBeginCheckoutGTMEvent(cart));

    // We want to retrigger each time we are enabled
    // We *do not* want to retrigger on every change to the cart, only when the items in it or their quantities change
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, hashOfCartItems]);

  const closeAddGiftCardModal = () => {
    //We close the modal but the last voucher we added had an error, we remove it
    if (addVoucherError && addVoucherVariables) {
      removeVoucherMutation(addVoucherVariables.voucherCode);
    }

    setModalState({ state: "hidden" });
    reset();
    // we need to delay the focus to ensure the modal is closed before focusing the button
    if (modalState.state === "open") setTimeout(() => modalState?.button?.focus());
  };

  const addGiftCard = async (cardIdentifier: string, secret: string) => {
    await addGiftCardMutation({ cardIdentifier, secret });
    closeAddGiftCardModal();
  };

  const addVoucher = async (voucherCode: string) => {
    addVoucherMutation(
      { voucherCode },
      {
        onSuccess: () => {
          closeAddGiftCardModal();
        },
      },
    );
  };

  return (
    <>
      {stylingComponent}
      {!!cart && (
        <GiftCardList
          giftCards={payment?.giftCards ?? []}
          totalAfterGiftCards={payment?.amountToPay ?? 0}
          onAddGiftCard={(e) => {
            setModalState({ state: "open", button: e.currentTarget });
            resetVoucherMutation();
          }}
          onRemoveGiftCard={({ cardIdentifier }) => removeGiftCard(cardIdentifier)}
          disabled={isLoading}
        />
      )}

      {cart && payment ? (
        payment.paymentProvider === "Klarna" ? (
          <KlarnaCheckout cartId={cart.cartGuid} />
        ) : payment.paymentProvider === "Nets" ? (
          <NetsCheckout
            cartId={cart.cartGuid}
            locale={locale}
            theme={paymentStyling?.nets}
            shopUrlSlugOverrides={shopUrlSlugOverrides}
          />
        ) : payment.paymentProvider === "ZeroAmount" ? (
          <ZeroCostCheckout cartId={cart.cartGuid} shopUrlSlugOverrides={shopUrlSlugOverrides} />
        ) : (
          `ERROR: Unsupported payment provider ${(payment as { paymentProvider: string }).paymentProvider}`
        )
      ) : (
        // The KlarnaCheckout component will handle these states, once it's shown
        <>
          {isLoading && <CheckoutLoading />}
          {error && <CheckoutError />}
        </>
      )}

      <Modal
        isOpen={modalState.state === "open"}
        onClose={closeAddGiftCardModal}
        portalId={MODAL_PORTAL_ID}
        innerClassName={styles.modalInner}
        disableInitialFocusInModal
      >
        <div className={styles.modalContent}>
          <GiftCardAndVoucherForm
            giftCard={
              allowedToUseGiftCard
                ? {
                    type: "form",
                    giftCardFormProps: {
                      onSubmit: addGiftCard,
                      disabled: isLoading,
                      onCancel: closeAddGiftCardModal,
                      error: gcError ?? undefined,
                    },
                  }
                : {
                    type: "error",
                    modalContent: (
                      <>
                        <Banner
                          type="warning"
                          heading={t("cannotBePurchasedWithGiftCardHeading")}
                          paragraph={t("cannotBePurchasedWithGiftCard")}
                        />

                        <PrimaryButton
                          isFullWidth
                          complementary
                          onClick={closeAddGiftCardModal}
                          label={t("close")}
                          autoFocus
                          className={styles.giftCardCannotBeUsedCloseButton}
                        />
                      </>
                    ),
                  }
            }
            voucherFormProps={{
              onSubmit: addVoucher,
              onRemoveCodeErrorCode: () => {
                if (addVoucherError && addVoucherVariables) {
                  removeVoucherMutation(addVoucherVariables.voucherCode, { onSuccess: resetVoucherMutation });
                }
              },
              disabled: isLoading,
              isRemovingVoucher: removeVoucherPending,
              onCancel: closeAddGiftCardModal,
              error: voucherError ?? undefined,
            }}
          />
        </div>
      </Modal>
    </>
  );
});
