import { useTranslation } from "react-i18next";
import { useShopServiceCartContext, useStaticConfigContext } from "@/core/contexts";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { CheckoutLoading } from "@/core/components/primitives/shop-service-status/shop-service-status";
import { MyParksService } from "@/core/services";
import { AuthActionTypes } from "@/core/types";
import TextAndLineDivider from "@/core/components/primitives/text-and-line-divider/text-and-line-divider";
import { useCart, useFinalizeZeroAmountPayment, usePayment } from "@/core/hooks";
import { paymentToPurchaseGTMEvent, trackEcommerceEvent } from "@/core/helpers/gtm-helper";
import { navigate } from "gatsby-link";
import { TranslationWithWrappers } from "@/core/components/primitives/translation-with-wrappers/translation-with-wrappers";
import { LoginOrRegister } from "@/core/components/modules/login-or-register/login-or-register";
import styles from "./zero-cost-checkout.module.less";
import AuthAware from "../../hocs/auth-aware/auth-aware";
import Banner from "@/core/components/primitives/banner/banner";
import { isNonEmptyArray } from "@/core/helpers";
import { ShopUrlSlugOverrides } from "@/core/types/shop-service-types";

const parseApiErrors = (error: unknown) => {
  if (
    error &&
    typeof error === "object" &&
    "error" in error &&
    error.error &&
    typeof error.error === "object" &&
    "errors" in error.error &&
    isNonEmptyArray(error.error.errors)
  ) {
    return error.error.errors as Array<{ message?: string; errorCode: string }>;
  }
  return null;
};

export type ZeroCostCheckoutProps = {
  cartId: string;
  shopUrlSlugOverrides: ShopUrlSlugOverrides | undefined;
};
export const ZeroCostCheckout = AuthAware<ZeroCostCheckoutProps>(function ZeroCostCheckoutInner({
  cartId,
  shopUrlSlugOverrides,
  auth,
  dispatch,
}) {
  const { t } = useTranslation();

  const { eCommerce } = useStaticConfigContext();
  const { forgetCartIfActive } = useShopServiceCartContext();
  const { data: cart } = useCart(cartId);
  const { data: payment } = usePayment(cartId);
  const { mutateAsync: finalize, error, isPending: finalizing } = useFinalizeZeroAmountPayment(cartId);

  if (!auth || auth.isFetchingSession) {
    return <CheckoutLoading />;
  }

  if (!auth.isLoggedIn) {
    return (
      <div className={styles.card}>
        <LoginOrRegister auth={auth} dispatch={dispatch} notLoggedInMessage={t("checkoutLoginToCheckoutZeroCost")} />
      </div>
    );
  }

  const finalizePurchase = async () => {
    if (!auth.cookieString || !cart || !payment) {
      throw new Error(
        `Missing required data to finalize zero cost checkout (missing? cookieString=${!auth.cookieString}, cart=${!cart}, payment=${!payment}`,
      );
    }

    await finalize(auth.cookieString);
    forgetCartIfActive(cartId);
    trackEcommerceEvent(paymentToPurchaseGTMEvent(cart, payment));

    const confirmationSlug = shopUrlSlugOverrides?.confirmationUrl ?? eCommerce.shopServiceConfirmationSlug;

    navigate(`${confirmationSlug}?cartId=${cartId}`);
  };

  const [contactLabel, interpolation] = auth.user?.phoneNo
    ? (["checkoutLoggedInAsContactPhone", auth.user.phoneNo] as const)
    : (["checkoutLoggedInAsContactEmail", auth.user?.email ?? ""] as const);
  const translationOptions = {
    firstName: auth.user?.firstName ?? "Okänd",
    lastName: auth.user?.lastName ?? "Efternamn",
    contact: "UNUSED", // We use a nested TranslationWithWrappers for this
  };

  return (
    <div className={styles.card}>
      <p className="heading-xs">{t("checkoutLoggedIn")}</p>
      {error && (
        <Banner
          type="critical"
          heading={t("somethingWentWrong")}
          paragraph={parseApiErrors(error)?.[0]?.message ?? t("somethingWentWrong")}
        />
      )}
      <p>
        <TranslationWithWrappers
          label="checkoutLoggedInAs"
          interpolation={translationOptions}
          wrappers={{
            firstName: (s) => <b>{s}</b>,
            lastName: (s) => <b>{s}</b>,
            contact: () => (
              <TranslationWithWrappers
                label={contactLabel}
                interpolation={[interpolation]}
                wrappers={{ [0]: (s) => <b>{s}</b> }}
              />
            ),
          }}
        />
      </p>
      <div>
        <PrimaryButton
          onClick={finalizePurchase}
          isDisabled={finalizing}
          label={t("checkoutFinalizePurchase")}
          isFullWidth
        />
      </div>
      <TextAndLineDivider text={t("orDivider")} />
      <div>
        <PrimaryButton
          onClick={() => {
            MyParksService.deleteSession().then(() => {
              dispatch({ type: AuthActionTypes.SESSION_DELETED });
            });
          }}
          isDisabled={finalizing}
          label={t("checkoutChangeUser")}
          isFullWidth
          complementary
        />
      </div>
    </div>
  );
});
