import { GiftCardPaymentResponseItem } from "@parksandresorts/webapiproxy-types";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { useTranslation } from "react-i18next";
import { CurrencyHelper, isNonEmptyArray } from "@/core/helpers";
import SummaryList from "@/core/components/primitives/summary-list/summary-list";
import styles from "./gift-card-list.module.less";
import { TranslationWithWrappers } from "@/core/components/primitives/translation-with-wrappers/translation-with-wrappers";
import { SummaryTotal } from "@/core/components/primitives/summary-total/summary-total";
import { formatGiftCardCode } from "@/core/components/primitives/gift-card-form/gift-card-form";
import { SpokenText } from "@/core/components/primitives/spoken-text/spoken-text";
import { MouseEventHandler } from "react";

export type Props = {
  giftCards: Array<GiftCardPaymentResponseItem>;
  totalAfterGiftCards: number;
  disabled?: boolean;

  onAddGiftCard: MouseEventHandler<HTMLButtonElement>;
  onRemoveGiftCard: (giftCard: GiftCardPaymentResponseItem) => void;
};
export function GiftCardList({ giftCards, totalAfterGiftCards, disabled, onAddGiftCard, onRemoveGiftCard }: Props) {
  const { t } = useTranslation();

  const totalGiftCardAmount = giftCards.reduce((sum, card) => sum + card.reservedAmount, 0);

  return (
    <div
      className={styles.container}
      data-contentful-label-id="giftCardList.listTitle"
      role="region"
      aria-live="polite"
      aria-relevant="all"
    >
      {isNonEmptyArray(giftCards) && (
        <SummaryList
          category={t("giftCardList.listTitle")}
          preExpanded
          quantity={t("summaryStepPieces", { count: giftCards.length })}
          sumPrice={"− " + CurrencyHelper.formatToSekWithPossiblePrecision(totalGiftCardAmount)}
        >
          <div className={styles.listWrapper}>
            {giftCards.map((giftCard, index) => (
              <div key={index} className={styles.listItem}>
                <span>
                  <SpokenText text={t("giftCardList.numberSpokenText")} />
                  {formatGiftCardCode(giftCard.cardIdentifier)}
                </span>
                <span className={styles.amount}>
                  − {CurrencyHelper.formatToSekWithPossiblePrecision(giftCard.reservedAmount)}
                </span>
                <i className="body-s" data-contentful-label-id="giftCardList.remainingBalance">
                  <TranslationWithWrappers
                    label="giftCardList.remainingBalance"
                    interpolation={[CurrencyHelper.formatToSekWithPossiblePrecision(giftCard.balanceAfterPayment)]}
                    wrappers={{ 0: (s) => <b>{s}</b> }}
                  />
                </i>
                <PrimaryButton
                  className={styles.removeButton}
                  complementary
                  iconCenterNew="trash"
                  ariaLabel={t("remove")}
                  onClick={() => onRemoveGiftCard(giftCard)}
                  isDisabled={disabled}
                />
              </div>
            ))}
          </div>
        </SummaryList>
      )}
      <PrimaryButton
        className={styles.useGiftCardButton}
        onClick={onAddGiftCard}
        testId="use-gift-card-button"
        data-contentful-label-id="useGiftCardOrVoucher"
        label={t("useGiftCardOrVoucher")}
        isDisabled={disabled}
      />
      {isNonEmptyArray(giftCards) && (
        <SummaryTotal type="price" labelId="giftCardList.subtotal" price={totalAfterGiftCards} />
      )}
    </div>
  );
}
