import styles from "./gift-card-and-voucher-form.module.less";
import { GiftCardForm } from "@/core/components/primitives/gift-card-form/gift-card-form";
import { VoucherForm } from "@/core/components/primitives/voucher-form/voucher-form";
import { ComponentProps, useEffect, useState } from "react";
import SegmentedControls from "@/core/components/primitives/segmented-controls/segmented-controls";
import { useTranslation } from "react-i18next";

type Props = {
  giftCard:
    | { type: "form"; giftCardFormProps: ComponentProps<typeof GiftCardForm> }
    | { type: "error"; modalContent: React.ReactNode };
  voucherFormProps: ComponentProps<typeof VoucherForm>;
};

export const GiftCardAndVoucherForm = ({ giftCard, voucherFormProps }: Props) => {
  const [selectedOption, setSelectedOption] = useState<"giftCard" | "voucher">("voucher");
  const { t } = useTranslation();

  //If the content switches directly when changing the segmented control, it can cause layout shift.
  //To mitigate this, we introduce a slight delay before updating the displayed content.
  const [delayedSelectedOption, setDelayedSelectedOption] = useState<"giftCard" | "voucher">("voucher");
  useEffect(() => {
    const timeout = setTimeout(() => {
      setDelayedSelectedOption(selectedOption);
    }, 100);
    return () => clearTimeout(timeout);
  }, [selectedOption]);

  return (
    <div className={styles.wrapper}>
      <SegmentedControls
        className={styles.segmentedControl}
        name="gift-card-or-voucher"
        dateKey=""
        segments={[
          { label: t("voucherCode"), value: "voucher" },
          { label: t("giftCard"), value: "giftCard" },
        ]}
        selectedValue={selectedOption}
        onChange={(value) => {
          setSelectedOption(value);
          if (value !== "voucher") {
            voucherFormProps.onRemoveCodeErrorCode();
          }
        }}
      />
      {delayedSelectedOption === "giftCard" && giftCard.type === "form" && (
        <GiftCardForm {...giftCard.giftCardFormProps} />
      )}
      {delayedSelectedOption === "giftCard" && giftCard.type === "error" && giftCard.modalContent}
      {delayedSelectedOption === "voucher" && <VoucherForm {...voucherFormProps} />}
    </div>
  );
};
GiftCardAndVoucherForm.displayName = "GiftCardAndVoucherForm";
