import InputField from "@/core/components/primitives/input-field/input-field";
import { useTranslation } from "react-i18next";
import { OutlineButton, PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import styles from "./gift-card-form.module.less";
import { debounce } from "lodash-es";
import { useMemo, useState } from "react";
import InputLabel from "@/core/components/primitives/input-label/input-label";
import InputError from "@/core/components/primitives/input-error/input-error";
import InputHelperText from "@/core/components/primitives/input-helper-text/input-helper-text";
import { LabelKey } from "@/core/labels/i18n";
import Banner, { BannerProps } from "@/core/components/primitives/banner/banner";

type Props = {
  onSubmit: (cardNumber: string, code: string) => void;
  onCancel?: () => void;
  /** disbled can be used to prevent editing, for example when checking the validity of the gift card */
  disabled?: boolean;
  error?: Pick<BannerProps, "heading" | "paragraph">;
};

/** adds space every 4 characters */
export const formatGiftCardCode = (value: string) => {
  return value.replace(/(.{4})/g, "$1 ").trim();
};

const checkCardNumber = (value: string): undefined | LabelKey => {
  if (value.length !== 8) {
    return "giftCardForm.numberLenghtErrorMessage";
  }
  return undefined;
};

const checkCode = (value: string): undefined | LabelKey => {
  if (!value) {
    return "inputValidationRequired";
  }
  return undefined;
};

export const GiftCardForm = ({ onSubmit, onCancel, disabled, error: bannerError }: Props) => {
  const { t } = useTranslation();

  const [cardNumber, setCardNumber] = useState<string>();
  const [code, setCode] = useState<string>();
  const cardNumberIncludingPrefix = t("giftCardForm.numberPrefix") + (cardNumber ?? "");

  const [cardNumberErrorText, setCardNumberErrorText] = useState<LabelKey | undefined>(undefined);
  const [codeErrorText, setCodeErrorText] = useState<LabelKey>();

  const checkCardNumberOnDebounce = useMemo(
    () => debounce((newValue: string) => setCardNumberErrorText(checkCardNumber(newValue)), 3_000),
    [],
  );
  const checkCodeOnDebounce = useMemo(
    () => debounce((newValue: string) => setCodeErrorText(checkCode(newValue)), 3_000),
    [],
  );

  const giftCardNumberPrefixWithSpace = formatGiftCardCode(t("giftCardForm.numberPrefix"));

  const submit = () => {
    if (disabled) return;

    // recheck for errors, in case debounce hasn't run yet
    const instantCardNumberErrorText = checkCardNumber(cardNumber ?? "");
    const instantCodeErrorText = checkCode(code ?? "");
    setCardNumberErrorText(instantCardNumberErrorText);
    setCodeErrorText(instantCodeErrorText);

    if (!instantCardNumberErrorText && !instantCodeErrorText && cardNumber && code) {
      onSubmit(cardNumberIncludingPrefix, code);
    }
  };

  const formatCodeWithSpace = (value: string) => {
    const digits = value.replace(/\D/g, "").slice(0, 8); // max 8 digits
    return formatGiftCardCode(digits);
  };

  return (
    <div className={styles.formWrapper}>
      {bannerError && <Banner type="critical" border {...bannerError} announcement="assertive" />}
      <div className={styles.cardNumberInput}>
        <InputLabel label={t("giftCardForm.number")} inputName="cardNumber" id="labelForCardNumber" isRequired={true} />
        <InputField
          value={giftCardNumberPrefixWithSpace}
          size={giftCardNumberPrefixWithSpace.length}
          className={styles.lockedInputPrefix}
          icon="lock"
          readOnly
          isValid={!cardNumberErrorText}
          focus={false}
          aria-labelledby="labelForCardNumber"
        />
        <InputField
          name="cardNumber"
          placeholder={t("giftCardForm.numberPlaceholder")}
          value={formatCodeWithSpace(cardNumber ?? "")}
          inputMode="numeric"
          onChange={(_name, rawValue) => {
            const unformatted = rawValue.replace(/\D/g, "").slice(0, 8); // keep raw digits
            checkCardNumberOnDebounce(unformatted);
            setCardNumber(unformatted);
          }}
          isValid={!cardNumberErrorText}
          focus
          disabled={disabled}
          onKeyDown={(e) => {
            if (e.key === "Enter") submit();
          }}
        />

        {!cardNumberErrorText && <InputHelperText helperText={t("giftCardForm.numberHelperText")} />}
        <InputError showError={!!cardNumberErrorText} errorText={cardNumberErrorText && t(cardNumberErrorText)} />
      </div>
      <div>
        <InputField
          name="code"
          placeholder={t("giftCardForm.codePlaceholder")}
          label={t("giftCardForm.code")}
          isRequired
          value={code}
          onChange={(_name, value) => {
            checkCodeOnDebounce(value);
            setCode(value);
          }}
          isValid={!codeErrorText}
          disabled={disabled}
          onKeyDown={(e) => {
            if (e.key === "Enter") submit();
          }}
          helperText={t("giftCardForm.codeHelperText")}
          errorText={codeErrorText && t(codeErrorText)}
        />
      </div>

      <div className={styles.buttonRow}>
        <OutlineButton size="medium" label={t("cancel")} isFullWidth onClick={() => onCancel?.()} />
        <PrimaryButton
          size="medium"
          testId="use-gift-card-button"
          label={t("use")}
          isDisabled={disabled}
          isFullWidth
          onClick={submit}
        />
      </div>
    </div>
  );
};
GiftCardForm.displayName = "GiftCardForm";
